<?php $workRows=$listing['rows']; ?>
<?php if($layout==='board'): ?>
<p class="footnote">Drag a card to another state to update its workflow. Open a card to edit details.</p><div class="work-board" data-work-board data-project="<?= e($project['id']) ?>"><?php foreach($states as $state):$column=array_values(array_filter($workRows,fn($row)=>(int)$row['state_id']===(int)$state['id'])); ?><section class="work-board-column <?= $state['wip_limit']!==null&&(int)$state['active_count']>(int)$state['wip_limit']?'is-over-wip':'' ?>" data-work-state="<?= e($state['id']) ?>" data-work-wip-count="<?= (int)$state['active_count'] ?>" data-work-wip-limit="<?= e($state['wip_limit']??'') ?>"><header><span class="work-state-dot" data-work-color="<?= e($state['color']) ?>"></span><strong><?= e($state['name']) ?></strong><span><?= count($column) ?></span></header><?php if($state['wip_limit']!==null): ?><p class="work-wip-summary <?= (int)$state['active_count']>(int)$state['wip_limit']?'work-wip-warning':'' ?>" <?= (int)$state['active_count']>(int)$state['wip_limit']?'role="status"':'' ?>>Active WIP <?= (int)$state['active_count'] ?> / <?= (int)$state['wip_limit'] ?><?= (int)$state['active_count']>(int)$state['wip_limit']?' - Over limit':'' ?></p><?php endif; ?><div class="work-board-cards"><?php foreach($column as $workRow): ?><article class="work-board-card" draggable="<?= $listing['filters']['scope']==='active'&&$project['status']!=='archived'?'true':'false' ?>" data-work-card="<?= e($workRow['id']) ?>" data-version="<?= e($workRow['version']) ?>"><div class="work-card-top"><span><?= e($workRow['key']) ?> <span class="work-type-tag type-<?= e($workRow['issue_type']) ?>"><?= e(WorkService::TYPES[$workRow['issue_type']]) ?></span></span><span class="work-priority priority-<?= e($workRow['priority']) ?>"><?= e(WorkService::PRIORITIES[$workRow['priority']]) ?></span></div><a href="/work/issue/<?= e($workRow['id']) ?>"><?= e($workRow['title']) ?></a><?php if($workRow['labels']): ?><div class="work-labels"><?php foreach($workRow['labels'] as $label): ?><span data-work-color="<?= e($label['color']) ?>"><?= e($label['name']) ?></span><?php endforeach; ?></div><?php endif; ?><div class="work-card-footer"><span><?= $workRow['due_date']?e($workRow['due_date']):'No due date' ?></span><span class="work-assignee-avatars"><?php foreach(array_slice($workRow['assignees'],0,3) as $person): ?><span class="work-avatar" title="<?= e($person['name']) ?>"><?= e(mb_substr($person['name'],0,1)) ?></span><?php endforeach; ?></span></div></article><?php endforeach; ?><?php if(!$column): ?><div class="work-board-empty">No work items</div><?php endif; ?></div></section><?php endforeach; ?></div><p class="footnote" data-work-board-status aria-live="polite"></p>
<?php elseif($layout==='calendar'): $first=new DateTimeImmutable($month.'-01');$days=(int)$first->format('t');$offset=(int)$first->format('N')-1;$prev=$first->modify('-1 month')->format('Y-m');$next=$first->modify('+1 month')->format('Y-m'); ?>
<section class="card"><div class="section-heading"><h2><?= e($first->format('F Y')) ?></h2><div class="hero-actions"><a href="<?= $workPath ?>?<?= e($workQuery(['month'=>$prev])) ?>">← Previous</a><a href="<?= $workPath ?>?<?= e($workQuery(['month'=>$next])) ?>">Next →</a></div></div><div class="work-calendar"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day): ?><strong class="work-calendar-day"><?= $day ?></strong><?php endforeach;for($i=0;$i<$offset;$i++): ?><div class="work-calendar-blank"></div><?php endfor;for($day=1;$day<=$days;$day++):$date=$month.'-'.str_pad((string)$day,2,'0',STR_PAD_LEFT); ?><div class="work-calendar-cell <?= $date===date('Y-m-d')?'today':'' ?>"><time><?= $day ?></time><?php foreach($workRows as $workRow):if($workRow['due_date']!==$date)continue; ?><a href="/work/issue/<?= e($workRow['id']) ?>" data-work-color="<?= e($workRow['state_color']) ?>"><small><?= e($workRow['key']) ?></small><?= e($workRow['title']) ?></a><?php endforeach; ?></div><?php endfor; ?></div><p class="footnote">The calendar uses each work item’s due date. Items without a due date are not placed on the grid.</p></section>
<?php elseif($layout==='gantt'): $rangeStart=new DateTimeImmutable($month.'-01');$rangeEnd=$rangeStart->modify('last day of this month');$dayCount=(int)$rangeEnd->format('j'); ?>
<section class="card"><div class="section-heading"><h2>Project timeline · <?= e($rangeStart->format('F Y')) ?></h2><div class="hero-actions"><a href="<?= $workPath ?>?<?= e($workQuery(['month'=>$rangeStart->modify('-1 month')->format('Y-m')])) ?>">←</a><a href="<?= $workPath ?>?<?= e($workQuery(['month'=>$rangeStart->modify('+1 month')->format('Y-m')])) ?>">→</a></div></div><div class="work-timeline"><div class="work-timeline-header"><span>Work item</span><div><?php for($day=1;$day<=$dayCount;$day++): ?><small><?= $day ?></small><?php endfor; ?></div></div><?php $timelineCount=0;foreach($workRows as $workRow):if(!$workRow['start_date']||!$workRow['due_date'])continue;$start=new DateTimeImmutable($workRow['start_date']);$end=new DateTimeImmutable($workRow['due_date']);if($end<$rangeStart||$start>$rangeEnd)continue;$timelineCount++;$startDay=max(0,(int)$rangeStart->diff(max($rangeStart,$start))->format('%a'));$endDay=min($dayCount-1,(int)$rangeStart->diff(min($rangeEnd,$end))->format('%a')); ?><div class="work-timeline-row"><a href="/work/issue/<?= e($workRow['id']) ?>"><small><?= e($workRow['key']) ?></small><?= e($workRow['title']) ?></a><div><a class="work-timeline-bar" href="/work/issue/<?= e($workRow['id']) ?>" data-work-color="<?= e($workRow['state_color']) ?>" data-work-left="<?= $startDay/$dayCount*100 ?>" data-work-width="<?= max(1,$endDay-$startDay+1)/$dayCount*100 ?>" title="<?= e($workRow['start_date'].' → '.$workRow['due_date']) ?>"><?= e($workRow['title']) ?></a></div></div><?php endforeach; ?></div><?php if(!$timelineCount): ?><p class="muted">No matching items have a start and due date within this month. Add both dates to place a work item on the timeline.</p><?php endif; ?><p class="footnote">Bars use real start and due dates. No dates are inferred from creation time.</p></section>
<?php else: ?>
<?php if(!$workRows): ?><section class="card empty"><h3>No matching work items.</h3><p>Create a work item below or change your filters.</p></section><?php else: ?>
<?php if($layout==='list'): ?><section class="card work-list"><form id="work-bulk" method="post" action="<?= $workPath ?>/bulk" class="work-bulk"><?= csrf_field() ?><strong>Bulk update</strong><select name="field" data-work-bulk-field><option value="state_id">State</option><option value="priority">Priority</option><option value="cycle_id">Cycle</option><option value="module_id">Module</option><option value="issue_type">Type</option><option value="fix_version_id">Fix version</option></select><select name="value" data-work-bulk-values aria-label="Bulk update value"><?php foreach($states as $state): ?><option data-field="state_id" value="<?= e($state['id']) ?>"><?= e($state['name']) ?></option><?php endforeach;foreach(WorkService::PRIORITIES as $value=>$label): ?><option data-field="priority" value="<?= $value ?>" hidden disabled><?= e($label) ?></option><?php endforeach; ?><option data-field="cycle_id" value="" hidden disabled>No cycle</option><?php foreach($cycles as $cycle): ?><option data-field="cycle_id" value="<?= e($cycle['id']) ?>" hidden disabled><?= e($cycle['name']) ?></option><?php endforeach; ?><option data-field="module_id" value="" hidden disabled>No module</option><?php foreach($modules as $module): ?><option data-field="module_id" value="<?= e($module['id']) ?>" hidden disabled><?= e($module['name']) ?></option><?php endforeach; ?><?php foreach(WorkService::TYPES as $value=>$label): ?><option data-field="issue_type" value="<?= $value ?>" hidden disabled><?= e($label) ?></option><?php endforeach; ?><option data-field="fix_version_id" value="" hidden disabled>No release</option><?php foreach($releases as $release): ?><option data-field="fix_version_id" value="<?= e($release['id']) ?>" hidden disabled><?= e($release['name']) ?></option><?php endforeach; ?></select><button class="secondary">Update selected</button></form><?php foreach($workRows as $workRow): ?><article class="work-list-row"><input type="checkbox" name="ids[]" value="<?= e($workRow['id']) ?>" form="work-bulk" aria-label="Select <?= e($workRow['key']) ?>"><input type="hidden" name="versions[<?= e($workRow['id']) ?>]" value="<?= e($workRow['version']) ?>" form="work-bulk"><span class="work-state-dot" data-work-color="<?= e($workRow['state_color']) ?>" title="<?= e($workRow['state_name']) ?>"></span><a class="work-list-main" href="/work/issue/<?= e($workRow['id']) ?>"><small><?= e($workRow['key']) ?></small><strong><?= e($workRow['title']) ?></strong><small class="work-type-meta"><?= e(WorkService::TYPES[$workRow['issue_type']]) ?><?= $workRow['fix_version_name']?' / '.e($workRow['fix_version_name']):'' ?></small></a><span class="work-priority priority-<?= e($workRow['priority']) ?>"><?= e(WorkService::PRIORITIES[$workRow['priority']]) ?></span><span class="work-list-due"><?= e($workRow['due_date']??'—') ?></span><span class="work-assignee-avatars"><?php foreach(array_slice($workRow['assignees'],0,2) as $person): ?><span class="work-avatar" title="<?= e($person['name']) ?>"><?= e(mb_substr($person['name'],0,1)) ?></span><?php endforeach; ?></span></article><?php endforeach; ?></section>
<?php else: ?><section class="card work-spreadsheet"><p class="footnote">Edit a cell and press Save. Each cell checks the work item’s version before writing.</p><div class="table-wrap"><table><thead><tr><th>Work item</th><th>Type</th><th>Fix version</th><th>State</th><th>Priority</th><th>Due date</th><th>Estimate</th></tr></thead><tbody><?php foreach($workRows as $workRow): ?><tr><td><a href="/work/issue/<?= e($workRow['id']) ?>"><?= e($workRow['key']) ?></a><strong><?= e($workRow['title']) ?></strong></td><?php foreach(['issue_type'=>'Type','fix_version_id'=>'Fix version','state_id'=>'State','priority'=>'Priority','due_date'=>'Due date','estimate'=>'Estimate'] as $field=>$fieldLabel): ?><td><form method="post" action="<?= $workPath ?>/issues/<?= e($workRow['id']) ?>/field"><?= csrf_field() ?><input type="hidden" name="version" value="<?= e($workRow['version']) ?>"><input type="hidden" name="field" value="<?= $field ?>"><?php if($field==='issue_type'): ?><select name="value" aria-label="Type for <?= e($workRow['key']) ?>"><?php foreach(WorkService::TYPES as $value=>$label): ?><option value="<?= $value ?>" <?= $workRow['issue_type']===$value?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><?php elseif($field==='fix_version_id'): ?><select name="value" aria-label="Fix version for <?= e($workRow['key']) ?>"><option value="">No release</option><?php foreach($releases as $release): ?><option value="<?= e($release['id']) ?>" <?= $workRow['fix_version_id']==$release['id']?'selected':'' ?>><?= e($release['name']) ?></option><?php endforeach; ?></select><?php elseif($field==='state_id'): ?><select name="value" aria-label="State for <?= e($workRow['key']) ?>"><?php foreach($states as $state): ?><option value="<?= e($state['id']) ?>" <?= $state['id']===$workRow['state_id']?'selected':'' ?>><?= e($state['name']) ?></option><?php endforeach; ?></select><?php elseif($field==='priority'): ?><select name="value" aria-label="Priority for <?= e($workRow['key']) ?>"><?php foreach(WorkService::PRIORITIES as $key=>$label): ?><option value="<?= $key ?>" <?= (int)$workRow['priority']===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><?php else: ?><input type="<?= $field==='due_date'?'date':'number' ?>" name="value" value="<?= e($workRow[$field]??'') ?>" <?= $field==='estimate'?'min="0" max="1000" step="0.5"':'' ?> aria-label="<?= e($fieldLabel.' for '.$workRow['key']) ?>"><?php endif; ?><button class="quiet">Save</button></form></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></section><?php endif;endif;endif; ?>
